function evalTree(node: GbrTreeNode, x: number[]): number {
  let cur: GbrTreeNode = node;
  while (Array.isArray(cur)) {
    cur = x[cur[0]] <= cur[1] ? cur[2] : cur[3];
  }
  return cur;
}

